"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import "@/components/iso/iso.css";
import "./workbench.css";

/*
 * Hero workbench: one test bed, three products taking turns on it.
 * A morph takes the current product apart top-first (assemblies lift, fade and blur away,
 * ease-in) and builds the next one bottom-up (assemblies drop into place, ease-out),
 * while the bench stays put. The readout tags each assembly as it lands.
 * Art is generated by anatomy/workbench/build.mjs and loaded after first paint.
 */

type Product = { id: string; code: string; name: string; parts: number; asms: readonly string[]; svg: string };
type Workbench = { W: number; H: number; bench: string; products: readonly Product[] };

const HOLD_MS = 4200; // how long a finished product stays on the bench
const OUT_MS = 520;
const OUT_STAGGER = 55;
const IN_MS = 680;
const IN_STAGGER = 120;
const EASE_IN = "cubic-bezier(0.55, 0, 0.8, 0.25)";
const EASE_OUT = "cubic-bezier(0.22, 1, 0.36, 1)";
const lift = (i: number) => 46 + i * 9; // screen units an assembly travels

const pad = (n: number) => String(n).padStart(2, "0");

export default function HeroWorkbench() {
  const [data, setData] = useState<Workbench | null>(null);
  const [current, setCurrent] = useState(0);
  const [tag, setTag] = useState("");
  const groups = useRef<Array<SVGGElement | null>>([]);
  const busy = useRef(false);
  const paused = useRef(false);
  const currentRef = useRef(0);
  const reduce = useRef(false);

  useEffect(() => {
    reduce.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let alive = true;
    import("./workbenchArt").then((m) => alive && setData(m.WORKBENCH as unknown as Workbench));
    return () => {
      alive = false;
    };
  }, []);

  const itemsOf = (g: SVGGElement | null) => {
    const byAsm = new Map<number, SVGGElement[]>();
    g?.querySelectorAll<SVGGElement>(":scope > .wb-it").forEach((el) => {
      const a = Number(el.dataset.asm);
      if (!byAsm.has(a)) byAsm.set(a, []);
      byAsm.get(a)!.push(el);
    });
    return byAsm;
  };

  const settledTag = useCallback((p: Product) => `${p.code} · ${p.name} · ${p.parts} parts`, []);

  const buildIn = useCallback(
    (index: number, startDelay = 0) => {
      if (!data) return 0;
      const p = data.products[index];
      const g = groups.current[index];
      if (!g) return 0;
      const byAsm = itemsOf(g);
      g.style.display = "";
      g.animate([{ filter: "blur(6px)" }, { filter: "blur(0px)" }], { duration: 260 + p.asms.length * IN_STAGGER, delay: startDelay, easing: EASE_OUT, fill: "backwards" });
      p.asms.forEach((name, i) => {
        const delay = startDelay + i * IN_STAGGER;
        (byAsm.get(i) ?? []).forEach((el) =>
          el.animate(
            [
              { transform: `translate(0px, ${-lift(i)}px)`, opacity: 0 },
              { transform: "translate(0px, 0px)", opacity: 1 },
            ],
            { duration: IN_MS, delay, easing: EASE_OUT, fill: "backwards" },
          ),
        );
        window.setTimeout(() => setTag(`${p.code} · ASM-${pad(i + 1)} ${name}`), delay + IN_MS * 0.55);
      });
      const total = startDelay + (p.asms.length - 1) * IN_STAGGER + IN_MS;
      window.setTimeout(() => setTag(settledTag(p)), total);
      return total;
    },
    [data, settledTag],
  );

  // Show the first product, built up once the art arrives.
  useEffect(() => {
    if (!data) return;
    const g = groups.current[0];
    if (!g) return;
    g.style.display = "";
    if (reduce.current) {
      setTag(settledTag(data.products[0]));
      return;
    }
    buildIn(0, 250);
  }, [data, buildIn, settledTag]);

  const takeOut = useCallback(
    (index: number) => {
      if (!data) return 0;
      const p = data.products[index];
      const g = groups.current[index];
      if (!g) return 0;
      const byAsm = itemsOf(g);
      const n = p.asms.length;
      const total = (n - 1) * OUT_STAGGER + OUT_MS;
      g.animate([{ filter: "blur(0px)" }, { filter: "blur(6px)" }], { duration: total, easing: EASE_IN, fill: "forwards" });
      for (let i = n - 1; i >= 0; i--) {
        const delay = (n - 1 - i) * OUT_STAGGER;
        (byAsm.get(i) ?? []).forEach((el) =>
          el.animate(
            [
              { transform: "translate(0px, 0px)", opacity: 1 },
              { transform: `translate(0px, ${-lift(i)}px)`, opacity: 0 },
            ],
            { duration: OUT_MS, delay, easing: EASE_IN, fill: "forwards" },
          ),
        );
      }
      window.setTimeout(() => {
        g.style.display = "none";
        g.getAnimations({ subtree: true }).forEach((a) => a.cancel());
      }, total + 30);
      return total;
    },
    [data],
  );

  const goTo = useCallback(
    (next: number) => {
      if (!data || busy.current || next === currentRef.current) return;
      busy.current = true;
      const prev = currentRef.current;
      currentRef.current = next;
      setCurrent(next);
      if (reduce.current) {
        groups.current[prev]!.style.display = "none";
        groups.current[next]!.style.display = "";
        setTag(settledTag(data.products[next]));
        busy.current = false;
        return;
      }
      const outMs = takeOut(prev);
      const inMs = buildIn(next, outMs * 0.6);
      window.setTimeout(() => (busy.current = false), Math.max(outMs, inMs) + 50);
    },
    [data, takeOut, buildIn, settledTag],
  );

  // The cycle: hold, then morph to the next product. Paused on hover and when the tab is hidden.
  useEffect(() => {
    if (!data || reduce.current) return;
    const id = window.setInterval(() => {
      if (paused.current || busy.current || document.hidden) return;
      goTo((currentRef.current + 1) % data.products.length);
    }, HOLD_MS + 1800);
    return () => window.clearInterval(id);
  }, [data, goTo]);

  return (
    <div
      className="iso workbench relative flex h-full w-full flex-col items-center"
      data-theme="light"
      onPointerEnter={() => (paused.current = true)}
      onPointerLeave={() => (paused.current = false)}
    >
      <div className="relative min-h-0 w-full flex-1">
        {data && (
          <svg
            className="iso-svg wb-svg absolute inset-0 h-full w-full"
            viewBox={`0 0 ${data.W} ${data.H}`}
            preserveAspectRatio="xMidYMid meet"
            role="img"
            aria-label={`A workbench where hardware products are assembled in turn: a planetary rover, a tool cabinet and a circuit-board test fixture. Now showing: ${data.products[current].name}.`}
          >
            <g dangerouslySetInnerHTML={{ __html: data.bench }} />
            {data.products.map((p, i) => (
              <g
                key={p.id}
                ref={(el) => {
                  groups.current[i] = el;
                }}
                style={{ display: i === 0 ? undefined : "none" }}
                dangerouslySetInnerHTML={{ __html: p.svg }}
              />
            ))}
          </svg>
        )}
      </div>

      {/* readout: product, assembly landing, and dots to jump between products */}
      <div className="mt-1 flex items-center gap-4 font-mono text-[11px] tracking-[0.04em] text-neutral-500">
        <span aria-live="polite" className="rounded-full bg-white/80 px-3 py-1 text-center tabular-nums shadow-[0_0_0_1px_rgba(10,10,11,0.05)] backdrop-blur-md">
          {tag || " "}
        </span>
      </div>
      {data && (
        <div className="mt-2 flex items-center gap-2" role="tablist" aria-label="Products on the bench">
          {data.products.map((p, i) => (
            <button
              key={p.id}
              type="button"
              role="tab"
              aria-selected={i === current}
              aria-label={p.name}
              onClick={() => goTo(i)}
              className={`h-1.5 rounded-full transition-all duration-500 ${i === current ? "w-6 bg-brand" : "w-1.5 bg-black/15 hover:bg-black/30"}`}
            />
          ))}
        </div>
      )}
    </div>
  );
}
